def transform(grid):
 h,w=len(grid),len(grid[0])
 colors={v for row in grid for v in row if v}
 candidates=[]
 for v in colors:
  pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==v]
  a,b=min(r for r,c in pts),max(r for r,c in pts)
  l,t=min(c for r,c in pts),max(c for r,c in pts)
  if b-a>=2 and t-l>=2:
   edge=sum(r in (a,b) or c in (l,t) for r,c in pts)
   ratio=edge/(2*(b-a+t-l))
   if ratio>.5:candidates.append((edge*ratio,v,a,b,l,t))
 out=[[0]*w for _ in range(h)]
 if not candidates:return out
 _,v,a,b,l,t=max(candidates)
 seen=set()
 for r in range(h):
  for c in range(w):
   if not grid[r][c] or grid[r][c]==v or (r,c) in seen:continue
   col=grid[r][c];stack=[(r,c)];seen.add((r,c));comp=[]
   while stack:
    x,y=stack.pop();comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     xx,yy=x+dx,y+dy
     if 0<=xx<h and 0<=yy<w and (xx,yy) not in seen and grid[xx][yy]==col:
      seen.add((xx,yy));stack.append((xx,yy))
   if all(a<x<b and l<y<t for x,y in comp):
    for x,y in comp:out[x][y]=col
 return out

